{
  "part": {
    "name": "Splined toothed drive wheel",
    "description": "Two-solid, thin circular drive component comprising a separate internally splined hub insert and a lightweight wheel body. The wheel body has a central hub collar, curved load-carrying spokes, multiple weight-reduction openings, a reinforced outer rim, and a repeated circumferential tooth profile.",
    "source_views": [
      "front",
      "back",
      "left",
      "right",
      "top",
      "bottom",
      "toprightiso"
    ],
    "symmetry_note": "The principal rotation axis is the STEP Y-axis. The outer tooth system and internal spline are rotationally repeated. The wheel web is approximately rotationally balanced but its openings and spoke widths are not a simple continuous surface of revolution. Front and back geometry are not mirror-identical because the hub insert, recesses, and edge treatments differ. STEP data reports two separate solids."
  },
  "Section": [
    {
      "id": "S01",
      "name": "Splined hub insert",
      "features included": [
        "separate central insert solid",
        "internal multi-tooth spline bore",
        "front annular mounting land",
        "external cylindrical locating diameter",
        "front entry chamfer",
        "rear annular flange and recess",
        "lobed external torque-transfer profile"
      ],
      "function intent": "Couples the wheel to a splined shaft and transfers torque between the shaft and the surrounding wheel hub while providing axial and radial location.",
      "physical behavior": "The numerous internal spline flanks share circumferential shear load and constrain relative rotation. The cylindrical outside diameter and annular lands locate the insert concentrically and resist radial displacement, while the lobed exterior and rear flange transmit torque and axial reaction into the wheel body.",
      "geometry": "A separate, short annular insert approximately 31.5 mm in outside diameter and 7.8 mm thick. It contains a finely toothed internal spline, a cylindrical outer body, a front chamfered rim, rear stepped annular surfaces, and a non-circular lobed interface visible around the central bore.",
      "location": "At the exact center of the part, coaxial with the wheel rotation axis; visually dark in the front, back, and isometric views.",
      "colour": {
        "R": 220,
        "G": 70,
        "B": 70
      },
      "major_faces": [
        {
          "face_code": "0000",
          "name": "Front annular land",
          "Brep_id": "FACE 1",
          "description": "Large planar front-facing annulus of the separate spline insert."
        },
        {
          "face_code": "0001",
          "name": "Front outer chamfer",
          "Brep_id": "FACE 0",
          "description": "Conical entry band blending the front land into the external diameter."
        },
        {
          "face_code": "0002",
          "name": "External locating cylinder",
          "Brep_id": "FACE 2",
          "description": "Cylindrical outside surface that radially locates the insert in the wheel hub."
        },
        {
          "face_code": "0003",
          "name": "Rear insert land",
          "Brep_id": "FACE 233",
          "description": "Principal planar rear-facing surface of the spline insert and its rear flange."
        },
        {
          "face_code": "0004",
          "name": "Rear recessed floor",
          "Brep_id": "FACE 215",
          "description": "Planar annular step within the rear side of the insert."
        },
        {
          "face_code": "0005",
          "name": "Internal shoulder land",
          "Brep_id": "FACE 224",
          "description": "Broad planar annular shoulder between the front portion and the deeper rear spline region."
        },
        {
          "face_code": "0006",
          "name": "Representative spline flank",
          "Brep_id": "FACE 3",
          "description": "One representative longitudinal planar flank from the repeated internal spline tooth system."
        }
      ],
      "minor_faces_Brep_id": [
        "FACE 4-FACE 194 (inclusive: remaining spline flanks, spline lands, root patches, and small connecting facets)",
        "FACE 195-FACE 214 (inclusive: rear lobed flange side patches and local blends)",
        "FACE 216-FACE 223 (inclusive: recessed rear transition walls)",
        "FACE 225-FACE 232 (inclusive: remaining annular recess walls)"
      ],
      "relationships": [
        {
          "source id": "S01",
          "target id": "S02",
          "function relationship": "transmits_load, locates_mating_part, constrains_dof, mounts_to",
          "structural relationship": "coaxial_with, contained_in, attached_to"
        },
        {
          "source id": "S01",
          "target id": "S03",
          "function relationship": "transmits_load",
          "structural relationship": "offset_from, supported_by"
        }
      ]
    },
    {
      "id": "S02",
      "name": "Main hub collar",
      "features included": [
        "central annular collar in the wheel body",
        "insert receiving cavity",
        "front annular rim",
        "front chamfer",
        "cylindrical cavity wall",
        "rear annular seat",
        "large rear toroidal blend",
        "conical load-spreading transition"
      ],
      "function intent": "Receives and supports the splined insert, maintains concentricity, and spreads shaft torque and radial load into the spoke system.",
      "physical behavior": "The annular collar acts as a stiff hoop around the insert. Its cylindrical wall resists radial bearing pressure, the front and rear lands react axial forces, and the conical and toroidal transitions reduce stress concentration where the compact hub expands into the thinner web.",
      "geometry": "A thick annular boss surrounding the insert. It has stepped planar lands, a short cylindrical receiving wall, chamfered entry, and smoothly blended transitions into the spoke roots.",
      "location": "Centered around S01, between the spline insert and the inner ends of the spokes.",
      "colour": {
        "R": 50,
        "G": 120,
        "B": 220
      },
      "major_faces": [
        {
          "face_code": "0007",
          "name": "Front hub annulus",
          "Brep_id": "FACE 667",
          "description": "Planar front annular seat immediately surrounding the spline insert."
        },
        {
          "face_code": "0008",
          "name": "Hub entry chamfer",
          "Brep_id": "FACE 668",
          "description": "Conical front edge treatment around the insert receiving opening."
        },
        {
          "face_code": "0009",
          "name": "Insert receiving wall",
          "Brep_id": "FACE 669",
          "description": "Cylindrical hub surface coaxial with and surrounding the separate insert."
        },
        {
          "face_code": "0010",
          "name": "Conical hub transition",
          "Brep_id": "FACE 432",
          "description": "Broad conical transition that spreads load from the central collar toward the spoke roots."
        },
        {
          "face_code": "0011",
          "name": "Rear hub blend",
          "Brep_id": "FACE 580",
          "description": "Large toroidal blend around the back of the central collar."
        },
        {
          "face_code": "0012",
          "name": "Rear annular seat",
          "Brep_id": "FACE 581",
          "description": "Planar rear-facing annulus adjoining the rear hub blend."
        }
      ],
      "minor_faces_Brep_id": [
        "FACE 619-FACE 666 (inclusive: repeated front and rear chamfers, cylindrical patches, and small annular transition facets around the hub cavity)"
      ],
      "relationships": [
        {
          "source id": "S02",
          "target id": "S01",
          "function relationship": "locates_mating_part, constrains_dof, transmits_load",
          "structural relationship": "contains, coaxial_with, supports"
        },
        {
          "source id": "S02",
          "target id": "S03",
          "function relationship": "transmits_load, distributes_stress",
          "structural relationship": "attached_to, blends_into, supports"
        },
        {
          "source id": "S02",
          "target id": "S04",
          "function relationship": "transmits_load",
          "structural relationship": "coaxial_with, offset_from"
        }
      ]
    },
    {
      "id": "S03",
      "name": "Spoke and lightweight web",
      "features included": [
        "curved radial spokes",
        "large weight-reduction openings",
        "smaller intermediate openings",
        "front planar web lands",
        "rear planar web lands",
        "spoke-root fillets",
        "opening perimeter walls",
        "outer web transition into the rim"
      ],
      "function intent": "Connects the central hub to the outer toothed rim with low mass while maintaining torsional stiffness, radial stiffness, and balanced load distribution.",
      "physical behavior": "The curved spokes primarily carry combined tension, compression, bending, and in-plane shear as torque passes between hub and rim. Wide spoke roots and continuous fillets spread stress at the hub and rim junctions. The openings remove low-utilization material and reduce rotational inertia while retaining closed load paths.",
      "geometry": "An open circular web with multiple smoothly curved spokes and rounded windows. The front and back contain broad planar lands, while the opening walls and spoke transitions are formed by BSpline, cylindrical, and toroidal patches with generous fillets.",
      "location": "Radially between the main hub collar and the outer toothed rim.",
      "colour": {
        "R": 60,
        "G": 180,
        "B": 110
      },
      "major_faces": [
        {
          "face_code": "0013",
          "name": "Front web land",
          "Brep_id": "FACE 496",
          "description": "Largest planar front-facing web surface surrounding the spoke openings."
        },
        {
          "face_code": "0014",
          "name": "Front outer spoke blend",
          "Brep_id": "FACE 492",
          "description": "Representative toroidal front blend where a spoke group approaches the outer rim."
        },
        {
          "face_code": "0015",
          "name": "Representative opening wall",
          "Brep_id": "FACE 333",
          "description": "Large curved BSpline wall forming part of a major weight-reduction opening."
        },
        {
          "face_code": "0016",
          "name": "Rear opening blend",
          "Brep_id": "FACE 317",
          "description": "Representative rear toroidal fillet around an outer spoke or window transition."
        },
        {
          "face_code": "0017",
          "name": "Rear web land",
          "Brep_id": "FACE 312",
          "description": "Large planar rear-facing web surface visible around the openings."
        },
        {
          "face_code": "0018",
          "name": "Outer web cylindrical band",
          "Brep_id": "FACE 513",
          "description": "Representative cylindrical band joining the spoke web to the reinforced outer rim."
        }
      ],
      "minor_faces_Brep_id": [
        "FACE 234-FACE 311 (inclusive)",
        "FACE 313-FACE 316 (inclusive)",
        "FACE 318-FACE 332 (inclusive)",
        "FACE 334-FACE 431 (inclusive)",
        "FACE 433-FACE 491 (inclusive)",
        "FACE 493-FACE 495 (inclusive)",
        "FACE 497-FACE 512 (inclusive)",
        "FACE 514-FACE 579 (inclusive)",
        "FACE 582-FACE 618 (inclusive)"
      ],
      "relationships": [
        {
          "source id": "S03",
          "target id": "S02",
          "function relationship": "transmits_load, distributes_stress",
          "structural relationship": "attached_to, blends_into, supported_by"
        },
        {
          "source id": "S03",
          "target id": "S04",
          "function relationship": "transmits_load, distributes_stress, supports",
          "structural relationship": "attached_to, blends_into, shares_face"
        },
        {
          "source id": "S03",
          "target id": "S01",
          "function relationship": "provides_clearance",
          "structural relationship": "offset_from, coaxial_with"
        }
      ]
    },
    {
      "id": "S04",
      "name": "Outer reinforced toothed rim",
      "features included": [
        "continuous annular rim",
        "repeated external drive teeth",
        "tooth tip crowns",
        "tooth leading and trailing flanks",
        "root valleys",
        "front rim land",
        "rear rim land",
        "front and rear edge fillet bands"
      ],
      "function intent": "Interfaces with an external chain, belt, or mating toothed component and converts tangential contact force into torque carried by the wheel.",
      "physical behavior": "Individual teeth experience localized contact pressure and bending at their roots. The thick annular rim distributes tooth loads circumferentially before transferring them into several spokes. Rounded roots and edge blends reduce bending stress concentration and improve resistance to impact, wear, and edge chipping.",
      "geometry": "A thick circular rim at the maximum radius, carrying a regular series of outward-projecting teeth. Each tooth is assembled from planar, cylindrical, conical, toroidal, and BSpline patches. Broad front and rear annular lands are joined to the tooth flanks by multi-stage rounded and chamfered bands.",
      "location": "Outermost circumference of the wheel, surrounding the spoke web.",
      "colour": {
        "R": 235,
        "G": 165,
        "B": 45
      },
      "major_faces": [
        {
          "face_code": "0019",
          "name": "Front rim land",
          "Brep_id": "FACE 778",
          "description": "Broad planar front-facing annular land at the base of the external teeth."
        },
        {
          "face_code": "0020",
          "name": "Front tooth-edge blend",
          "Brep_id": "FACE 940",
          "description": "Representative toroidal front blend running between the rim land and tooth side geometry."
        },
        {
          "face_code": "0021",
          "name": "Representative leading tooth flank",
          "Brep_id": "FACE 710",
          "description": "One planar flank from the repeated external tooth profile."
        },
        {
          "face_code": "0022",
          "name": "Representative tooth crown",
          "Brep_id": "FACE 711",
          "description": "One convex cylindrical crown patch at the outer tip of a tooth."
        },
        {
          "face_code": "0023",
          "name": "Representative trailing tooth flank",
          "Brep_id": "FACE 713",
          "description": "Opposing planar flank adjoining the representative tooth crown."
        },
        {
          "face_code": "0024",
          "name": "Representative tooth root transition",
          "Brep_id": "FACE 712",
          "description": "Conical root or valley transition between adjacent tooth-side patches."
        },
        {
          "face_code": "0025",
          "name": "Rear tooth-edge blend",
          "Brep_id": "FACE 1157",
          "description": "Representative toroidal blend connecting the tooth system to the rear rim land."
        },
        {
          "face_code": "0026",
          "name": "Rear rim land",
          "Brep_id": "FACE 941",
          "description": "Broad planar rear-facing annular land at the base of the teeth."
        }
      ],
      "minor_faces_Brep_id": [
        "FACE 670-FACE 709 (inclusive)",
        "FACE 714-FACE 777 (inclusive)",
        "FACE 779-FACE 939 (inclusive)",
        "FACE 942-FACE 1156 (inclusive)",
        "FACE 1158-FACE 1481 (inclusive)"
      ],
      "relationships": [
        {
          "source id": "S04",
          "target id": "S03",
          "function relationship": "transmits_load, distributes_stress, mounts_to",
          "structural relationship": "attached_to, blends_into, supported_by"
        },
        {
          "source id": "S04",
          "target id": "S02",
          "function relationship": "transmits_load",
          "structural relationship": "coaxial_with, offset_from"
        },
        {
          "source id": "S04",
          "target id": "S01",
          "function relationship": "transmits_load",
          "structural relationship": "coaxial_with, offset_from"
        }
      ]
    }
  ]
}
